package net.civeira.phylax.features.access.oauthclient.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;
import net.civeira.phylax.features.access.oauthclient.domain.OauthClientBackchannelTokenDeliveryModeOptions;

class BackchannelTokenDeliveryModeVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property backchannel token delivery mode of oauth client ")
  void test_backchannel_token_delivery_mode_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class,
        () -> BackchannelTokenDeliveryModeVO.tryFrom("_POLL_"));
    Assertions.assertEquals(OauthClientBackchannelTokenDeliveryModeOptions.POLL,
        BackchannelTokenDeliveryModeVO.tryFrom("POLL").getBackchannelTokenDeliveryMode()
            .orElse(null));
    Assertions.assertFalse(
        BackchannelTokenDeliveryModeVO.nullValue().getBackchannelTokenDeliveryMode().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(
        BackchannelTokenDeliveryModeVO.tryFrom(null).getBackchannelTokenDeliveryMode().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals(OauthClientBackchannelTokenDeliveryModeOptions.POLL,
        BackchannelTokenDeliveryModeVO.from(OauthClientBackchannelTokenDeliveryModeOptions.POLL)
            .getBackchannelTokenDeliveryMode().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> BackchannelTokenDeliveryModeVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + OauthClientBackchannelTokenDeliveryModeOptions.POLL + "]",
        BackchannelTokenDeliveryModeVO.from(OauthClientBackchannelTokenDeliveryModeOptions.POLL)
            .toString());
  }
}
